  function renderSalesStrategyTable() {
    const container = document.getElementById("ssTableContent");
    if (!container) return;
    const displayRangeSelect = document.getElementById("ssDisplayRangeSelect");
    if (displayRangeSelect) displayRangeSelect.value = getSsDisplayRangeId();
    const resolvedRows = buildSalesStrategyRowsResolved();
    state.lastSalesStrategyResolvedRows = resolvedRows;
    const { columns } = getSalesStrategyDisplayColumns();
    const colCount = 1 + columns.length;
    const bodyHtml = resolvedRows.length === 0 ? `<tr><td class="cell-empty" colspan="${colCount}">No draft sales yet \u2014 one is auto-added the moment you hold a ticker on the Past Purchases list above.</td></tr>` : resolvedRows.map((r, idx) => renderSalesStrategyRowHTML(r, idx, resolvedRows.length)).join("");
    const totalRowHtml = resolvedRows.length === 0 ? "" : buildSalesStrategyTotalRowHTML(resolvedRows, columns);
    container.innerHTML = `<div class="table-container"><table><thead><tr>${buildSalesStrategyHeaderRow()}</tr></thead><tbody>${totalRowHtml}${bodyHtml}</tbody></table></div>`;
    wireSalesStrategyEditing(container);
    wireSalesStrategyHeaderButtons(container.querySelector("thead"));
    renderSsHiddenColumnsNotice();
    renderBuyStrategyTable();
  }
  function showSaleRealizedConfirmDialog(resolvedRow) {
    return new Promise((resolve) => {
      const overlay = document.createElement("div");
      overlay.className = "dialog-backdrop";
      const panel = document.createElement("div");
      panel.setAttribute("role", "dialog");
      panel.setAttribute("aria-modal", "true");
      panel.className = "dialog-panel";
      const today2 = ppToday();
      panel.innerHTML = `
      <h3 class="dialog-title">Confirm sale of ${escHtml(resolvedRow.label || resolvedRow.ticker)}</h3>
      <div class="dialog-text">
        This adds a real sale row to the Lot Matching table above: <strong>${ppFmtNum(resolvedRow.unitsToSell)}</strong> unit(s) of <strong>${escHtml(resolvedRow.label || resolvedRow.ticker)}</strong> at <strong>$${Number(resolvedRow.sellingPrice).toFixed(2)}</strong>. Pick the date this sale actually happened.
      </div>
      <label class="dialog-field">Sale date
        <input id="ssConfirmDateInput" class="form-input" ${dateTextInputAttrs(today2)}>
      </label>
      <div class="dialog-actions">
        <button type="button" class="tab-btn" data-final="cancel">Cancel</button>
        <button class="btn-pad-wide" type="button" data-final="confirm">Confirm Sale</button>
      </div>`;
      overlay.appendChild(panel);
      document.body.appendChild(overlay);
      const dateInput = panel.querySelector("#ssConfirmDateInput");
      const finish = (value) => {
        document.removeEventListener("keydown", onKey);
        overlay.remove();
        resolve(value);
      };
      const onKey = (e) => {
        if (e.key === "Escape") finish(null);
      };
      document.addEventListener("keydown", onKey);
      panel.querySelector('[data-final="cancel"]').addEventListener("click", () => finish(null));
      panel.querySelector('[data-final="confirm"]').addEventListener("click", () => {
        const iso = parseDateTextToIso(dateInput.value);
        if (iso === null) {
          dateInput.style.outline = "1px solid var(--neg)";
          dateInput.title = "Use DD/MM/YYYY, e.g. 31/12/2026.";
          return;
        }
        finish(iso || today2);
      });
    });
  }
  function wireSalesStrategyEditing(container) {
    if (!container) return;
    container.querySelectorAll(".ss-input").forEach((el) => {
      el.addEventListener("change", (e) => {
        const id = e.target.getAttribute("data-row-id");
        const field = e.target.getAttribute("data-field");
        let value = parseFloat(e.target.value);
        if (isNaN(value)) value = 0;
        setSalesStrategyValue(id, field, value);
        renderSalesStrategyTable();
      });
      el.addEventListener("keydown", (e) => {
        if (e.key === "Enter") {
          e.preventDefault();
          el.blur();
        }
      });
    });
    container.querySelectorAll(".ss-move-btn").forEach((btn) => {
      btn.addEventListener("click", () => {
        moveSalesStrategyRow(btn.getAttribute("data-row-id"), parseInt(btn.getAttribute("data-dir"), 10));
        renderSalesStrategyTable();
      });
    });
    container.querySelectorAll(".ss-save-btn").forEach((btn) => {
      btn.addEventListener("click", () => {
        const id = btn.getAttribute("data-row-id");
        const tr = btn.closest("tr");
        const unitsInput = tr ? tr.querySelector("input[data-field='unitsToSell']") : null;
        const priceInput = tr ? tr.querySelector("input[data-field='sellingPrice']") : null;
        const units2 = unitsInput ? parseFloat(unitsInput.value) : 0;
        const price = priceInput ? parseFloat(priceInput.value) : 0;
        saveSalesStrategyRowAndSplit(id, isNaN(units2) ? 0 : units2, isNaN(price) ? 0 : price);
        renderSalesStrategyTable();
      });
    });
    container.querySelectorAll(".ss-dup-btn").forEach((btn) => {
      btn.addEventListener("click", () => {
        duplicateSalesStrategyRow(btn.getAttribute("data-row-id"));
        renderSalesStrategyTable();
      });
    });
    container.querySelectorAll(".ss-remove-btn").forEach((btn) => {
      btn.addEventListener("click", () => {
        const ticker = btn.getAttribute("data-ticker");
        const isRealized = btn.getAttribute("data-realized") === "1";
        const message = isRealized ? `Remove this completed "${ticker}" sale record from the Sales Strategy table? The real sale it created on Past Purchases/Lot Matching is NOT affected \u2014 this only removes it from this display.` : `Remove this draft "${ticker}" sale plan row? This only removes the plan \u2014 it was never a real sale.`;
        if (confirm(message)) {
          removeSalesStrategyRow(btn.getAttribute("data-row-id"));
          renderSalesStrategyTable();
        }
      });
    });
    container.querySelectorAll(".ss-confirm-btn").forEach((btn) => {
      btn.addEventListener("click", async () => {
        const id = btn.getAttribute("data-row-id");
        const resolvedRow = buildSalesStrategyRowsResolved().find((r) => r.id === id);
        if (!resolvedRow) return;
        if (resolvedRow.unitsToSell <= 0) {
          alert("Enter how many units to sell (greater than 0) before confirming the sale.");
          return;
        }
        const dateStr = await showSaleRealizedConfirmDialog(resolvedRow);
        if (!dateStr) return;
        realizeSalesStrategyRow(id, dateStr);
        renderPastPurchasesTable();
      });
    });
  }
