  function getPastPurchasesSortedRows2() {
    const rows = getPastPurchasesRows().slice();
    if (state.ppColumnSortState) {
      const { colId, direction } = state.ppColumnSortState;
      rows.sort((a, b) => {
        const va = colId === "asset" ? String(a.asset || "") : resolvePastPurchaseRowValues(a)[colId];
        const vb = colId === "asset" ? String(b.asset || "") : resolvePastPurchaseRowValues(b)[colId];
        let cmp;
        if (typeof va === "string" || typeof vb === "string") cmp = String(va).localeCompare(String(vb));
        else cmp = (va || 0) - (vb || 0);
        return direction === "asc" ? cmp : -cmp;
      });
      return rows;
    }
    const sortByParamLabel = (label, direction) => {
      const norm = (s) => String(s).trim().toLowerCase();
      const param = getPastPurchasesParams().find((p) => norm(p.label) === norm(label));
      if (!param) return;
      rows.sort((a, b) => {
        const va = resolvePastPurchaseRowValues(a)[param.id];
        const vb = resolvePastPurchaseRowValues(b)[param.id];
        let cmp;
        if (typeof va === "string" || typeof vb === "string") cmp = String(va || "").localeCompare(String(vb || ""));
        else cmp = (va || 0) - (vb || 0);
        return direction === "asc" ? cmp : -cmp;
      });
    };
    const sortMode = getPpSortMode();
    if (sortMode === "alpha") rows.sort((a, b) => String(a.asset).localeCompare(String(b.asset)));
    else if (sortMode === "date-new") rows.sort((a, b) => (b["dateAdded"] || 0) - (a["dateAdded"] || 0));
    else if (sortMode === "date-old") rows.sort((a, b) => (a["dateAdded"] || 0) - (b["dateAdded"] || 0));
    else if (sortMode === "param-date-purchased") sortByParamLabel("Date Purchased", "desc");
    else if (sortMode === "param-date-purchased-old") sortByParamLabel("Date Purchased", "asc");
    else if (sortMode === "param-date-sale") sortByParamLabel("Date Sale", "desc");
    else if (sortMode === "param-date-sale-old") sortByParamLabel("Date Sale", "asc");
    else if (sortMode === "param-sale-profit") sortByParamLabel("Realized Gain", "desc");
    else if (sortMode === "param-missed-gain") sortByParamLabel("Missed Gain %", "desc");
    return rows;
  }
